const dsnItems = $('🛰️ Fetch DSN Status XML').all().map(i => i.json);
const cmeItems = $('☀️ Fetch CME Data from NASA').all().map(i => i.json);
const goesItems = $('📡 Fetch GOES X-ray Data').all().map(i => i.json);
const neoItems = $('☄️ Fetch NEO Data from NASA').all().map(i => i.json);

const isActive = (val) => val === true || val === 'true' || val === 1 || val === '1';

let dsnDishes = [];
for (const item of dsnItems) {
  if (item.dsn && item.dsn.dish) {
    const dishes = Array.isArray(item.dsn.dish) ? item.dsn.dish : [item.dsn.dish];
    for (const dish of dishes) {
      const activity = dish.activity || 'Unknown';
      const isTracking = activity.includes('Telemetry');
      const hasDownlink = isActive(dish.downSignal?.active);
      const power = Number(dish.downSignal?.power) || 0;
      const anomaly = isTracking && (!hasDownlink || power < -400);
      dsnDishes.push({
        dish: dish.name, activity: activity, spacecraft: dish.target?.name || 'N/A',
        downActive: hasDownlink, dataRate: Number(dish.downSignal?.dataRate) || 0,
        band: dish.downSignal?.band || 'N/A', power: power, anomaly: anomaly
      });
    }
  }
}

const anomalies = dsnDishes.filter(d => d.anomaly);
const activeTracking = dsnDishes.filter(d => d.activity.includes('Telemetry') && d.downActive);
const maintenance = dsnDishes.filter(d => d.activity.includes('Maintenance') || d.activity.includes('Upgrades') || d.activity.includes('Calibration'));
const idle = dsnDishes.length - activeTracking.length - maintenance.length;

const anomalyStrings = anomalies.length > 0
  ? anomalies.map(a => `- ${a.dish} (${a.spacecraft}): ${!a.downActive ? 'downlink inactive' : 'low power'}, ${a.power} dBm`).join('\n')
  : 'None detected';

const activeTrackingStrings = activeTracking.length > 0
  ? activeTracking.map(a => `- ${a.dish} (${a.spacecraft}): ${a.band}-band, ${a.dataRate} bps, ${a.power} dBm`).join('\n')
  : 'None — all dishes in maintenance/idle';

const cmeData = cmeItems.filter(i => i.activityID);
const latestCME = cmeData[0] || null;

const goesData = goesItems.filter(i => i.flux !== undefined && Number(i.flux) > 0);
const latestXray = goesData.slice(-1)[0] || null;
let xrayVal = 0, xrayClass = 'Unknown';
if (latestXray) {
  xrayVal = Number(latestXray.flux);
  if (xrayVal >= 1e-4) xrayClass = 'X-class (Severe)';
  else if (xrayVal >= 1e-5) xrayClass = 'M-class (Elevated)';
  else if (xrayVal >= 1e-6) xrayClass = 'C-class (Moderate)';
  else if (xrayVal >= 1e-7) xrayClass = 'B-class (Low)';
  else xrayClass = 'A-class (Quiet)';
}

let neoData = [];
for (const item of neoItems) {
  if (item.near_earth_objects) {
    for (const date of Object.keys(item.near_earth_objects)) {
      const neos = item.near_earth_objects[date];
      if (Array.isArray(neos)) neoData.push(...neos);
    }
  }
}
const hazardousNEOs = neoData.filter(n => n.is_potentially_hazardous_asteroid === true || n.is_potentially_hazardous_asteroid === 'true');
const neoHazardStrings = hazardousNEOs.map(n => `${n.name} (${Number(n.estimated_diameter?.kilometers?.estimated_diameter_max || 0).toFixed(2)} km)`).join(', ');

return [{
  json: {
    timestamp: new Date().toISOString(),
    total_items: dsnItems.length + cmeItems.length + goesItems.length + neoItems.length,
    space_weather: {
      cme_count: cmeData.length, latest_cme_id: latestCME?.activityID || 'None',
      latest_cme_time: latestCME?.startTime || 'N/A', xray_flux_value: xrayVal.toExponential(2),
      xray_class: xrayClass, xray_time: latestXray?.time_tag || 'N/A'
    },
    dsn_operations: {
      total_dishes: dsnDishes.length, active_tracking_count: activeTracking.length,
      maintenance_count: maintenance.length, idle_count: idle, anomaly_count: anomalies.length,
      tracking_summary: `${activeTracking.length} tracking, ${maintenance.length} maintenance, ${idle} idle`,
      anomaly_strings: anomalyStrings, active_tracking_strings: activeTrackingStrings
    },
    neo: { count: neoData.length, hazardous_count: hazardousNEOs.length, hazardous_names: neoHazardStrings || 'None' }
  }
}];

parameters.text:
You are AEGIS-DSN, autonomous DSN and space weather monitoring AI.

DATA (FINAL pre-computed summary — DO NOT recalculate):

Timestamp: {{ $json.timestamp }}

SPACE WEATHER:
- CMEs detected: {{ $json.space_weather.cme_count }}
- Latest CME: {{ $json.space_weather.latest_cme_id }} at {{ $json.space_weather.latest_cme_time }}
- X-ray flux: {{ $json.space_weather.xray_flux_value }} W/m² ({{ $json.space_weather.xray_class }}) at {{ $json.space_weather.xray_time }}

DSN OPERATIONS:
- Dishes tracking: {{ $json.dsn_operations.tracking_summary }}
- Anomaly count: {{ $json.dsn_operations.anomaly_count }}
- Anomalies:
{{ $json.dsn_operations.anomaly_strings }}

NEAR-EARTH OBJECTS:
- Total tracked: {{ $json.neo.count }}
- Hazardous: {{ $json.neo.hazardous_count }} — {{ $json.neo.hazardous_names }}

STRICT RULES:
1. Do NOT recalculate X-ray class. Use value in parentheses.
2. Do NOT change spacecraft names. Copy from anomaly strings verbatim.
3. Do NOT add spacecraft names not present in data.
4. Output ONLY the final brief.

Format:
**STATUS:** [WARNING if anomalies > 3, CRITICAL if > 5, WATCH if 0-3, NOMINAL if 0 anomalies AND tracking > 0]
**SITUATION SUMMARY:** 2 lines explaining the data
**DSN NETWORK:** tracking count, maintenance count, anomalies
**SPACE WEATHER:** CME + X-ray with values
**NEO WATCH:** count + hazardous details
**RECOMMENDED ACTIONS:** 2 specific actions
**VERDICT:** 1-line assessment

Under 200 words. Copy all names and numbers verbatim. No hallucination.
